import {homeNavigation,homeDescent} from '../campus-layout.js';
import {StreetFinale} from './finale.js';
import {CityPressure} from './pressure.js';
import {escortCanFight} from './escort.js';
import {MissionManager} from '../../story/mission-manager.js';
import {exitTowardInterior} from '../../indoor-navigation.js';
import {FourthCombat} from './combat.js';
import {localCombatPath} from '../../chapter3/story/local-navigation.js';
import {CITY,TUNNEL,facilities,undergroundEntrances} from '../layout.js';
import {YUELU} from '../../chapter3/layout.js';
import {CHAZI,BRIDGE} from '../../regions/data.js';
import {CHAPTER4,newFourthState,STORY_ROOMS,OFFICE,WAREHOUSE,CONTROL,MARKET_EVENTS} from './missions.js';
import {FourthWorld,distance} from './world.js';
import {FourthActions} from './actions.js';
export class FourthChapter{
 constructor(parent){this.parent=parent;this.api=parent.api;this.$=parent.$;this.regionId=CITY;this.enemyLabel='商业保全的反击';this.active=false;this.manager=null;this.navigation=null;this.nextTime=0;this.combat=new FourthCombat(this);this.world=new FourthWorld(this);this.actions=new FourthActions(this);this.pressure=new CityPressure(this);this.finale=new StreetFinale(this);}
 state(){return this.manager?.state;}
 area(){return this.api.get().interior||'outside';}
 position(){const p=this.api.get().position;return[p[0],p[2]];}
 point(o){return[(o.local?this.api.interiors[o.area].ox:0)+o.at[0],o.at[1]];}
 routeFor(points,area=this.area()){return area==='outside'?points:this.api.interiors[area].route(points);}
 combatRoute([a,b]){return localCombatPath(a,b,{clear:(x,z)=>this.api.clearRegion(CITY,x,z,.6),heightAt:(x,z)=>this.world.region.heightAt(x,z)});}
 say(id,lines,channel='无线电'){if(lines?.length&&this.state())this.state().world.dialogueActors=[...this.world.contacts.entries(),...this.world.students.filter(e=>e.enabled).map(e=>[e.name,e])].filter(([,e])=>e.enabled).map(([name,e])=>({name,at:[e.g.position.x,e.g.position.z],area:e.area}));this.parent.dialogue.play(id,lines,channel);}
 boot(saved){this.pressure.clear();this.combat.reset();this.world.clear();this.api.carry(null);this.api.lockCityTime?.(false);this.active=!!saved;this.manager=null;this.navigation=null;this.nextTime=0;this.pendingActivation=null;this.finale.replay=null;if(saved)this.install(saved);else this.world.apply();}
 install(input){const base=newFourthState(),state=structuredClone(input);state.world={...base.world,...state.world,damage:{...state.world.damage},opened:{...base.world.opened,...state.world.opened},spentWeapons:{...state.world.spentWeapons},events:state.world.events||[]};
 if((state.revision||1)<2){const r=state.missions.c407;if(r?.status==='completed')r.currentObjective=CHAPTER4.at(-1).objectives.length;else if(r?.currentObjective===3){r.currentObjectiveId='c407-transmit';r.progress={};}if(state.currentMission==='c404'&&state.missions.c404?.currentObjective===2){const p=state.missions.c404.progress;p.elapsed=p.copyTime||0;p.started=!!p.copying;}if(state.currentMission==='c406'&&state.missions.c406?.currentObjective===1){const p=state.missions.c406.progress;p.pathIndex=0;}state.revision=2;}
 if(input.world?.boots==null){const record=state.missions.c401,school=CHAPTER4[0].objectives.findIndex(o=>o.id==='c401-school');state.world.boots=record?.status==='completed'||(record?.currentObjective??0)>school;}
 this.active=true;this.manager=new MissionManager(CHAPTER4,{world:s=>{this.world.apply();this.parent.state().chapterState.chapter4=s.chapterState.chapter4;this.syncTime();},banner:(a,b)=>this.parent.banner(a,b),dialogue:(id,lines,ch)=>this.say(id,lines,ch),objective:(o,p,restore)=>this.activate(o,p,restore),hud:(m,o,r)=>this.hud(m,o,r),save:()=>this.parent.save(),evaluate:(o,p,dt)=>this.evaluate(o,p,dt),event:(type,data)=>this.event(type,data),finishObjective:(o,p)=>this.finish(o,p),reward:r=>{if(r.personalMoney)this.api.cash(r.personalMoney);},deferNext:()=>{this.nextTime=2;},fail:r=>{this.world.clearEnemies();this.pressure.clear();this.parent.banner('目标中断',r);this.hud(this.manager.mission,this.manager.objective,this.manager.record);},reset:()=>{this.parent.dialogue.clear();this.pendingActivation=null;this.pressure.clear();this.api.closeFacilities();this.combat.reset();this.world.clearEnemies();this.api.recover(this.manager.record.checkpoint);},complete:s=>this.complete(s)},state,{chapterKey:'chapter4',finalStage:7});this.parent.third?.combat.reset();this.parent.second?.combat.reset();this.pressure.restore();if(this.parent.dialogue.busy)this.restoreDialogueActors();if(!state.currentMission&&!state.chapterComplete&&this.parent.dialogue.busy)this.nextTime=2;else this.manager.begin();if(this.manager.record?.status==='failed')this.manager.retry();this.world.apply();this.syncTime();this.combat.restoreHeld();this.$('#chapter2Plan').classList.add('hidden');this.$('#chapter2FreePlan').classList.add('hidden');this.$('#mobileDodge').classList.remove('hidden');this.$('#mobileHeat').classList.remove('hidden');this.markers();}
 restoreDialogueActors(){let actors=this.state().world.dialogueActors;if(!actors?.length){const previousMission=this.manager?.mission||[...CHAPTER4].reverse().find(m=>this.state().missions[m.id]?.status==='completed'),prev=this.manager?.mission?previousMission?.objectives[(this.manager.record?.currentObjective||0)-1]:previousMission?.objectives.at(-1);if(prev?.speaker)actors=[{name:prev.speaker,at:this.point(prev),area:prev.area}];else if(prev?.id==='c402-table'){const r=this.api.interiors.c4_mahjong;actors=[{name:'牌馆老板',at:[r.ox+4,4],area:r.id}];}else if(prev?.id==='c401-dismiss')actors=this.world.students.map((e,i)=>({name:e.name,at:[-198+i*1.8,402-i%2*2],area:'outside'}));else if(prev?.id==='c403-outfit'){const r=this.api.interiors.c4_heiwado_uniqlo;actors=[{name:'小朋友',at:[r.ox+4,20],area:r.id}];}}for(const a of actors||[]){const student=this.world.students.find(e=>e.name===a.name);if(student){student.enabled=true;this.world.place(student,a.at,a.area);}else this.world.contact(a.name,a.at,a.area);}}
 begin(){if(this.active||this.api.get().mapTest||!this.parent.third?.state()?.chapterComplete)return;const s=newFourthState(),old=this.parent.third.state().world;for(const k of['techniqueTraining','heavyGloves','heatCapacity','vehicleArmor'])if(old[k]!=null)s.world[k]=old[k];this.install(s);this.parent.save();}
 serialize(){
  if(this.manager){
   const w=this.state().world;
   if(w.pressure)w.pressure.enemies=this.world.streetEnemies.map(e=>({at:[e.g.position.x,e.g.position.z],role:e.role,hp:e.hp}));
   const o=this.manager.objective,p=this.manager.record?.progress;
   if(!this.pendingActivation&&this.manager.record?.status==='active'&&(o?.encounter==='escort'||o?.id==='c405-fight')){
    // Saving may occur after the physics step and its ally-hit knockback.
    this.world.preserve(p);const ally=this.world.contacts.get('田博');
    if(ally?.enabled)p.escortAt=[ally.g.position.x,ally.g.position.z];
   }
  }
  return this.manager?.serialize()||null;
 }
 syncTime(){const s=this.state();if(!s)return;this.api.lockCityTime(true);this.api.setCityTime(s.chapterComplete?s.world.cycleTime??(s.world.cycleNight?1320:600):s.world.time);}
 activate(o,p,restoring){if(!restoring||!this.manager.record.checkpoint)this.manager.record.checkpoint=this.api.checkpoint();if(this.parent.dialogue.busy){if(restoring)this.restoreDialogueActors();this.pendingActivation={o,p,restoring};return;}this.pendingActivation=null;this.state().world.dialogueActors=[];this.world.clearContacts();this.api.carry(this.state().world.ledgerRecovered?'电子总账':this.state().world.calibrationCard?'蓝袋校验卡':null);this.actions.begin(o,p);this.world.apply();this.markers();if(o.id==='c403-outfit'){if(!this.state().world.clothingFee){this.state().world.clothingFee=true;this.api.cash(59);}const r=this.api.interiors.c4_heiwado_uniqlo;this.world.contact('小朋友',r.safePoint(r.ox+4,20),o.area);}this.combat.restoreHeld();}
 evaluate(o,p,dt){const g=this.api.get();if(g.dead||g.mapTest||g.region!==CITY||this.parent.dialogue.busy||g.paused)return false;if(o.type==='streetShow')return!!p.finished;return this.actions.tick(o,p,dt);}
 event(type,data){const o=this.manager?.objective,p=this.manager?.record?.progress;if(!o||this.manager.record.status!=='active')return;this.actions.event(type,data,o,p);if(type==='damage'){this.world.preserve(p);if(data.entity===this.world.runner)p.targetHP=data.entity.hp;this.parent.save();}if(type==='hurt'&&p.copying){p.copying=false;this.api.toast('受伤打断了复制 · 靠近终端再试');this.parent.save();}}
 market(key){const e=MARKET_EVENTS[key],w=this.state().world;if(!e||w.events.includes(e.id))return false;w.events.push(e.id);const applied=this.api.marketEvent(e);this.parent.save();return applied;}
 finish(o,p){this.actions.finish(o,p);if(o.id==='c401-school')this.state().world.boots=true;if(o.id==='c401-dismiss'){this.state().world.time=1050;this.syncTime();}if(o.id==='c402-table')this.market('c402');if(o.id==='c404-office')this.market('cut');if(o.id==='c406-parking')this.market('c406');if(o.id==='c407-upload'){this.state().world.broadcastReady=true;}if(o.id==='c407-transmit'){this.state().world.broadcastArmed=true;}if(o.id==='c407-reveal')this.api.carry(null);this.navigation=null;}
 combatTarget(e){return this.actions.encounters.target(e,this.manager?.objective,this.manager?.record?.progress);}
 tick(dt,t){const g=this.api.get();if(this.pendingActivation&&!this.parent.dialogue.busy){const a=this.pendingActivation;this.activate(a.o,a.p,a.restoring);this.parent.save();}this.world.update(t);if(g.dead||g.paused||document.hidden)return;this.parent.dialogue.tick(dt);this.finale.tick(dt);if(this.parent.bannerTime>0){this.parent.bannerTime-=dt;if(this.parent.bannerTime<=0){this.$('#missionBanner').classList.add('hidden');this.$('#chapterResult').classList.add('hidden');}}
  if(this.state().chapterComplete){const w=this.state().world;if(w.completionPending&&!this.parent.dialogue.busy){w.completionPending=false;this.showComplete();this.parent.save();}if(g.region===CITY&&!w.completionPending&&!this.parent.dialogue.busy&&!this.finale.active()){w.cycleElapsed+=dt;if(w.cycleElapsed>=600){w.cycleElapsed%=600;w.cycleNight=!w.cycleNight;w.cycleTime=w.cycleNight?1320:600;this.syncTime();this.parent.save();}}}else if(this.nextTime>0&&!this.parent.dialogue.busy){this.nextTime-=dt;if(this.nextTime<=0)this.manager.startNext();}
  if(g.region===CITY){const o=this.manager.objective;this.pressure.tick(dt);if(o&&!this.parent.dialogue.busy&&['lure','tail','runner'].includes(o.type))this.actions.move(o,this.manager.record.progress,dt);this.combat.tick(dt);if(this.manager.record?.status==='active')this.manager.tick(dt);}else{for(const e of this.world.actors)e.intentX=e.intentZ=0;this.$('#chapter2Combat').classList.add('hidden');}if(this.parent.dialogue.busy)for(const e of this.world.actors)e.intentX=e.intentZ=0;this.markers();this.world.update(t);this.$('#hqBadge').classList.remove('hidden');this.$('#hqBadge').textContent=this.state().chapterComplete?'五一 · 放学以后':this.api.cityTimeLabel();
 }
 interact(){if(this.parent.dialogue.busy){this.parent.dialogue.next();return true;}const g=this.api.get();if(g.region!==CITY||g.mapTest||g.driving)return false;if(this.manager?.objective?.type==='streetShow'||this.state().chapterComplete){const done=this.finale.interact();if(done)this.parent.save();return done;}if(this.manager.record?.status!=='active')return false;if(this.actions.interact(this.manager.objective,this.manager.record.progress)){this.manager.tick(0);this.parent.save();return true;}return false;}
 shot(){return this.api.get().region===CITY?this.finale.shot():null;}
 prompt(){if(this.parent.dialogue.busy)return'继续对话';if(this.api.get().region!==CITY)return'';if(this.manager.record?.status==='failed')return'T 重试当前路段';if(this.manager?.objective?.type==='streetShow'||this.state().chapterComplete)return this.finale.prompt();return this.actions.prompt(this.manager.objective,this.manager.record?.progress);}
 priorityInteract(){const o=this.manager?.objective,p=this.manager?.record?.progress;if(this.parent.dialogue.busy)return this.interact();if(this.finale.ready()&&(o?.type==='streetShow'||this.state().chapterComplete))return this.interact();if(!o||!p||this.api.get().region!==CITY||this.api.get().driving||this.manager.record.status!=='active')return false;if((o.encounter||o.type==='upload')&&this.actions.encounters.prompt(o,p))return this.interact();return false;}
 allowAttack(){return!this.finale.active()&&!this.parent.dialogue.busy&&!(this.manager?.objective?.encounter==='escort'&&!escortCanFight(this.manager.record.progress))&&!(this.api.get().region===CITY&&this.manager.objective?.noAttack);}
 retry(){if(this.manager.record){this.manager.retry();this.parent.save();}}
 onDeath(){this.combat.reset();if(this.manager.record?.status==='active')this.manager.fail('豚师倒下了 · R 重生后从当前路段继续');this.parent.save();}
 onRespawn(){if(this.manager.record?.status==='failed')this.manager.retry();this.parent.save();}
 canEnter(id){if(!STORY_ROOMS.includes(id))return true;if(!this.active||this.api.get().mapTest)return false;const w=this.state().world;return this.state().chapterComplete||id===OFFICE&&w.guaranteeLead||id===WAREHOUSE&&(w.warehouseOpen||this.manager.objective?.id==='c406-breaker')||id===CONTROL&&w.ledgerRecovered;}
 billiardStairs(o,g){const shop=facilities.find(f=>f.id==='c4_billiards'),[x,z]=shop.at,[px,y,pz]=g.position,base=[x,z-14],climbing=Math.abs(px-x)<1.4&&pz>=base[1]-1&&pz<=z+1;
  if(o.area===shop.id&&y<3.6&&!climbing)return{at:base,label:'从外楼梯上二楼 · 八号台球厅'};
  if(o.area!==shop.id&&y>1&&climbing)return{at:base,label:'沿外楼梯下到解放西'};
  return null;
 }
 markers(){const o=this.manager?.objective,r=this.manager?.record,g=this.api.get();if(!o||r.status!=='active'||g.mapTest){this.navigation=null;this.updateNavigation();return;}let{at,area,label}=this.actions.destination(o,r.progress);if(g.region!==CITY){area='outside';if(g.region===TUNNEL){at=[335,-5.25];label='沿南湖隧道进入河东';}else if(g.region===YUELU){at=[810,75];label='驶向南湖隧道东向入口';}else if(g.region===CHAZI){at=[-810,318];label='经岳麓山道路前往南湖隧道';}else if(g.region===BRIDGE){at=[-500,0];label='先驶往观沙岭';}else{at=[385,450];label='从东北连接路返回五一商圈';}}else if(area!==this.area()){if(this.area()!=='outside'){let door=o.exit==='rear'?this.api.interiors[this.area()].exits.find(e=>e.name.includes('后门')):null;door||=exitTowardInterior(this.api.interiors,this.area(),area);if(door){at=door.at;label=door.name;area=this.area();}}else{at=facilities.find(f=>f.id===area)?.at||undergroundEntrances.reduce((a,b)=>distance(this.position(),a.at)<distance(this.position(),b.at)?a:b).at;label='进入 '+(this.api.interiors[area]?.name||'地下商业街');if(area==='c4_classroom_home')({at,label}=homeNavigation(g.position));area='outside';}}if(g.region===CITY&&this.area()==='outside'&&o.area==='outside'){const descent=homeDescent(g.position);if(descent)({at,label}=descent);}if(g.region===CITY&&this.area()==='outside'&&area==='outside'){const stairs=this.billiardStairs(o,g);if(stairs)({at,label}=stairs);}this.navigation=at?{at,area,region:g.region,label,meters:Math.round(distance(this.position(),at))}:null;this.updateNavigation();}
 updateNavigation(){const n=this.navigation;this.$('#missionNav').classList.toggle('hidden',!n);if(!n)return;this.$('#missionNavName').textContent=n.label;this.$('#missionNavDistance').textContent=n.meters+' m';const p=this.position(),a=Math.atan2(n.at[0]-p[0],p[1]-n.at[1])+(this.api.get().yaw||0);this.$('#missionNavArrow').style.transform='rotate('+a+'rad)';}
 hud(m,o,r){if(!m||!o)return;this.$('#missionHud').classList.remove('hidden');this.$('#chapterLabel').textContent='CHAPTER IV';this.$('#missionTitle').textContent=m.title;this.$('#missionObjective').textContent=r.status==='failed'?r.failure:o.text+this.actions.hint(o,r.progress);this.$('#storyRetry').classList.toggle('hidden',r.status!=='failed');this.$('#missionDistance').textContent=this.navigation?this.navigation.meters+' m':'';}
 complete(s){this.world.clearEnemies();this.world.apply();Object.assign(s.world,{cycleElapsed:0,cycleNight:true,cycleTime:s.world.time,completionPending:true});this.syncTime();this.navigation=null;this.updateNavigation();this.$('#missionHud').classList.add('hidden');this.$('#missionBanner').classList.add('hidden');this.parent.bannerTime=0;this.parent.state().chapterState.chapter4=7;this.parent.save();}
 showComplete(){this.parent.banner('CHAPTER IV COMPLETE','放学以后');this.parent.bannerTime=15;this.$('#chapterResult').classList.remove('hidden');this.$('#chapterResult').textContent='五一总账已公开 · 下一条线索：湘江中央 · 自由探索昼夜每 10 分钟交替';}
 drawMap(ctx,m,large){const n=this.navigation;if(!n||n.area!=='outside'||n.region!==this.api.get().region)return;const p=this.position();ctx.save();ctx.strokeStyle='#68cfff';ctx.lineWidth=large?3:2;ctx.setLineDash([7,4]);ctx.beginPath();ctx.moveTo(m.x(p[0]),m.z(p[1]));ctx.lineTo(m.x(n.at[0]),m.z(n.at[1]));ctx.stroke();ctx.restore();}
}
